def msort(a):
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    l = msort(a[:mid])
    r = msort(a[mid:])
    out = []
    i = j = 0
    while i < len(l) and j < len(r):
        if l[i] <= r[j]:
            out.append(l[i])
            i += 1
        else:
            out.append(r[j])
            j += 1
    while i < len(l):
        out.append(l[i])
        i += 1
    while j < len(r):
        out.append(r[j])
        j += 1
    return out
