def bfs(g, s, e):
    q = [[s]]
    seen = [s]
    while q:
        path = q.pop(0)
        node = path[-1]
        if node == e:
            return path
        for nxt in g[node]:
            if nxt not in seen:
                seen.append(nxt)
                q.append(path + [nxt])
    return None
