def pset(items):
    n = len(items)
    out = []
    for mask in range(2 ** n):
        cur = []
        for i in range(n):
            if mask % (2 ** (i + 1)) >= 2 ** i:
                cur.append(items[i])
        out.append(cur)
    return out
